#!/usr/bin/python
# Safe tar-package installer for the legacy Ubuntu 7/Python 2.5 host.
import os
import shutil
import stat
import sys
import tarfile
import tempfile

class UnsafeArchive(Exception):
    pass

def fail(message):
    sys.stderr.write('unpack: %s\n' % message)
    return 2

def safe_name(name):
    if not name:
        raise UnsafeArchive('empty member name')
    if name.startswith('/'):
        raise UnsafeArchive('absolute member path: %s' % name)
    parts = name.split('/')
    if '..' in parts:
        raise UnsafeArchive('parent traversal in member path: %s' % name)
    parts = [part for part in parts if part not in ('', '.')]
    if not parts:
        return '.'
    return '/'.join(parts)

def check_destination(incoming, stage):
    if os.path.lexists(incoming):
        mode = os.lstat(incoming).st_mode
        if not stat.S_ISDIR(mode):
            raise UnsafeArchive('incoming is not a real directory')
    for root, dirs, files in os.walk(stage):
        relroot = root[len(stage):].lstrip(os.sep)
        destroot = incoming if not relroot else os.path.join(incoming, relroot)
        if os.path.lexists(destroot):
            mode = os.lstat(destroot).st_mode
            if not stat.S_ISDIR(mode):
                raise UnsafeArchive('destination path is not a real directory: %s' % relroot)
        for name in dirs:
            rel = os.path.join(relroot, name) if relroot else name
            dest = os.path.join(incoming, rel)
            if os.path.lexists(dest):
                mode = os.lstat(dest).st_mode
                if not stat.S_ISDIR(mode):
                    raise UnsafeArchive('destination directory is unsafe: %s' % rel)
        for name in files:
            rel = os.path.join(relroot, name) if relroot else name
            dest = os.path.join(incoming, rel)
            if os.path.lexists(dest):
                mode = os.lstat(dest).st_mode
                if not stat.S_ISREG(mode):
                    raise UnsafeArchive('destination file is unsafe: %s' % rel)

def install_stage(incoming, stage):
    if not os.path.exists(incoming):
        os.mkdir(incoming, 0755)
    for root, dirs, files in os.walk(stage):
        relroot = root[len(stage):].lstrip(os.sep)
        destroot = incoming if not relroot else os.path.join(incoming, relroot)
        if not os.path.exists(destroot):
            os.mkdir(destroot, 0755)
        for name in dirs:
            dest = os.path.join(destroot, name)
            if not os.path.exists(dest):
                os.mkdir(dest, 0755)
        for name in files:
            os.rename(os.path.join(root, name), os.path.join(destroot, name))

def main():
    if len(sys.argv) != 2:
        return fail('usage: unpack ARCHIVE')
    base = os.path.realpath(os.path.join(os.path.dirname(__file__), '..'))
    incoming = os.path.join(base, 'incoming')
    stage = None
    archive = None
    try:
        archive = tarfile.open(sys.argv[1], 'r:*')
        members = archive.getmembers()
        for member in members:
            cleaned = safe_name(member.name)
            if member.issym() or member.islnk():
                raise UnsafeArchive('link member is not permitted: %s -> %s' % (member.name, member.linkname))
            if not (member.isfile() or member.isdir()):
                raise UnsafeArchive('special member is not permitted: %s' % member.name)
            if cleaned == '.' and not member.isdir():
                raise UnsafeArchive('invalid member path: %s' % member.name)
        stage = tempfile.mkdtemp(prefix='.unpack-', dir=base)
        for member in members:
            if safe_name(member.name) == '.' and member.isdir():
                continue
            archive.extract(member, stage)
        archive.close()
        archive = None
        check_destination(incoming, stage)
        install_stage(incoming, stage)
        return 0
    except (UnsafeArchive, tarfile.TarError, IOError, OSError), error:
        return fail(str(error))
    finally:
        if archive is not None:
            archive.close()
        if stage is not None:
            shutil.rmtree(stage, ignore_errors=True)

if __name__ == '__main__':
    sys.exit(main())
